import * as pdfjs from './vendor/pdf.mjs';
import {parsePage,mergePages,classify} from './parser.js';
import {createICS,berlinUTC} from './calendar.js';
pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;
const $=id=>document.getElementById(id);let people=[],selected=null,excluded=new Set(),generation=0,installPrompt;
function message(text,error=false){$('message').hidden=false;$('message').textContent=text;$('message').className=error?'error':''}
function reset(){generation++;people=[];selected=null;excluded.clear();$('pdf-file').value='';$('person').replaceChildren(new Option('Deinen Namen auswählen',''));$('duration').value='0';$('absence').checked=false;$('filename').textContent='';$('period').textContent='';$('rows').replaceChildren();$('count').textContent='';$('plan-panel').hidden=true;$('preview').hidden=true;$('upload-panel').hidden=false;$('message').hidden=true;$('reset').hidden=true;$('dropzone').disabled=false;$('download').disabled=true;$('phase').textContent='SCHRITT 01';$('work-title').textContent='Ein Plan. Dein Anfang.';setStep(1)}
function setStep(n){[1,2,3].forEach(i=>{const el=$('step'+i);el.classList.toggle('active',i<n);el.removeAttribute('aria-current');if(i===n)el.setAttribute('aria-current','step')})}
async function load(file){reset();if(!file)return;if(file.size>20*1024*1024){message('Die Datei ist größer als 20 MB. Bitte einen kleineren Dienstplan auswählen.',true);return}if(!/\.pdf$/i.test(file.name)){message('Bitte eine PDF-Datei auswählen.',true);return}const token=generation;$('dropzone').disabled=true;message('Dein PDF wird direkt auf diesem Gerät gelesen …');let task,doc;try{const data=new Uint8Array(await file.arrayBuffer());if(token!==generation)return;task=pdfjs.getDocument({data,isEvalSupported:false,useSystemFonts:true,cMapUrl:'./vendor/cmaps/',cMapPacked:true,standardFontDataUrl:'./vendor/standard_fonts/'});doc=await task.promise;if(doc.numPages>50)throw Error('Bitte einen Dienstplan mit höchstens 50 Seiten auswählen.');const pages=[];for(let i=1;i<=doc.numPages;i++){const page=await doc.getPage(i);const text=await page.getTextContent();pages.push(parsePage(text.items));page.cleanup()}if(token!==generation)return;people=mergePages(pages);if(!people.length)throw Error('Keine Dienstplantabelle erkannt. Gescannte PDFs werden nicht unterstützt. Bitte ein PDF mit auswählbarem Text verwenden.');for(const [i,p] of people.entries())$('person').add(new Option(p.name,String(i)));const dates=people.flatMap(p=>p.entries.map(e=>e.date)).sort();$('filename').textContent=file.name;$('period').textContent=`${formatDate(dates[0])} – ${formatDate(dates.at(-1))} · ${people.length} Personen`;$('plan-panel').hidden=false;$('upload-panel').hidden=true;$('reset').hidden=false;$('message').hidden=true;$('phase').textContent='SCHRITT 02';$('work-title').textContent='Finde deinen Namen.';setStep(2);$('person').focus()}catch(error){if(token===generation)message(error.name==='PasswordException'?'Dieses PDF ist passwortgeschützt. Bitte eine ungeschützte Version verwenden.':error.message||'Das PDF konnte nicht gelesen werden.',true)}finally{if(task)await task.destroy();if(token===generation)$('dropzone').disabled=false;$('pdf-file').value=''}}
function formatDate(date){return new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Europe/Berlin'}).format(new Date(date+'T12:00:00Z'))}
function visible(){return selected?selected.entries.filter(e=>{const c=classify(e.raw);return c.kind!=='absence'||($('absence').checked&&c.label==='Urlaub')}):[]}
function entries(){return visible().filter(e=>!excluded.has(e.date))}
function updateActions(){const list=entries();const ready=list.length>0&&(!list.some(e=>classify(e.raw).kind==='timed')||$('duration').value!=='');$('download').disabled=!ready;$('count').textContent=`${list.length} Einträge`;setStep(ready?3:2)}
function render(){selected=$('person').value===''?null:people[Number($('person').value)];$('preview').hidden=!selected;$('rows').replaceChildren();if(!selected){setStep(2);return}$('phase').textContent='SCHRITT 03';$('work-title').textContent='Deine Dienste. Dein Überblick.';for(const e of visible()){const c=classify(e.raw);const row=document.createElement('label');row.className='shift';const check=document.createElement('input');check.type='checkbox';check.checked=!excluded.has(e.date);check.setAttribute('aria-label',`${formatDate(e.date)} ${c.label} exportieren`);check.addEventListener('change',()=>{check.checked?excluded.delete(e.date):excluded.add(e.date);updateActions()});const date=document.createElement('span');date.className='date-box';date.append(e.date.slice(-2));const day=document.createElement('small');day.textContent=new Intl.DateTimeFormat('de-DE',{weekday:'short',month:'short',timeZone:'Europe/Berlin'}).format(new Date(e.date+'T12:00:00Z'));date.append(day);const desc=document.createElement('span');desc.className='shift-desc';const title=document.createElement('strong');title.textContent=c.label;const sub=document.createElement('small');sub.textContent=`Original: ${e.raw}`;desc.append(title,sub);const time=document.createElement('span');time.className='shift-time';if(c.kind==='timed'){time.textContent=c.time+' Uhr';if(Number($('duration').value)>0){const end=new Date(berlinUTC(e.date,c.time).getTime()+Number($('duration').value)*3600000);const endTime=new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',hour:'2-digit',minute:'2-digit'}).format(end);const nextDay=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).format(end)!==e.date;time.textContent+=' → '+endTime+(nextDay?' (+1 Tag)':'')}}else time.textContent='Ganztägig';row.append(check,date,desc,time);$('rows').append(row)}updateActions()}
function calendarFile(){return new File([createICS(selected.name,entries(),$('duration').value)],`Dienstplan-${selected.name.replace(/[^\p{L}\p{N}-]/gu,'_')}.ics`,{type:'text/calendar;charset=utf-8'})}
function download(file){const url=URL.createObjectURL(file);const a=document.createElement('a');a.href=url;a.download=file.name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);message('Die ICS-Datei wurde zum Download übergeben. Öffne sie mit einer Kalender-App, die ICS-Import unterstützt. Mehr dazu unten in der Hilfe.')}
$('dropzone').onclick=()=>$('pdf-file').click();$('pdf-file').onchange=e=>load(e.target.files[0]);$('reset').onclick=reset;$('clear').onclick=reset;$('person').onchange=()=>{excluded.clear();render()};$('duration').onchange=render;$('absence').onchange=render;$('download').onclick=()=>download(calendarFile());
for(const event of ['dragenter','dragover'])$('dropzone').addEventListener(event,e=>{e.preventDefault();$('dropzone').classList.add('drag')});for(const event of ['dragleave','drop'])$('dropzone').addEventListener(event,e=>{e.preventDefault();$('dropzone').classList.remove('drag')});$('dropzone').addEventListener('drop',e=>load(e.dataTransfer.files[0]));
window.addEventListener('pagehide',reset);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false});$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install').hidden=true}};if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
